	static readonly int LIBRARY_VERSION_COL = 1;
	static readonly int LIBRARY_VARIANT_COL = 2;
	static readonly int GHIDRA_VERSION_COL = 3;
	static readonly int GHIDRA_LANGUAGE_ID_COL = 4;
	static readonly int GHIDRA_LANGUAGE_VERSION_COL = 5;
	static readonly int GHIDRA_LANGUAGE_MINOR_VERSION_COL = 6;
